        // Penyimpanan aman: data yang sudah ada tidak pernah dianggap hilang hanya karena
        // file kosong, data baru, atau proses migrasi. Array kosong yang memang tersimpan
        // tetap dipertahankan sebagai pilihan pengguna.
        function loadStoredArray(key,fallback){
            try{
                const raw=localStorage.getItem(key);
                if(raw===null)return Array.isArray(fallback)?fallback:[];
                const parsed=JSON.parse(raw);
                return Array.isArray(parsed)?parsed:(Array.isArray(fallback)?fallback:[]);
            }catch(e){
                console.warn('Data lokal tidak dapat dibaca:',key,e);
                return Array.isArray(fallback)?fallback:[];
            }
        }
